void PeerManagerImpl::MaybeReconcile() {
    if (m_opts.txrecon_interval <= 0ms || !m_opts.txrelay_shortids) {
        return;
    }
    const auto tick_now{RelayTickNow()};
    if (tick_now < m_next_recon) {
        return;
    }
    m_next_recon = tick_now + m_opts.txrecon_interval;
    if (m_chainman.IsInitialBlockDownload()) {
        return;
    }
    const auto epoch{m_txrelay_index.Current()};
    if (!epoch) {
        return;
    }
    // Next negotiating peer after the last one, by id (round robin).
    NodeId next{-1};
    {
        LOCK(m_peer_mutex);
        NodeId first{-1};
        for (const auto &[id, peer] : m_peer_map) {
            if (!(peer->m_txrelay_features & txrelay::TXRELAY_RECON)) {
                continue;
            }
            if (first < 0) {
                first = id;
            }
            if (id > m_last_recon_peer) {
                next = id;
                break;
            }
        }
        if (next < 0) {
            next = first;
        }
    }
    if (next < 0) {
        return;
    }
    m_last_recon_peer = next;
    const auto summary{m_v2_protocol_handler.BuildSyncSummary(
        lotus::v2::net::ReconScope::LIVE_MEMPOOL, epoch->epoch_id, epoch->k0,
        epoch->k1)};
    uint64_t window{0};
    for (const auto &bucket : summary.buckets) {
        window += bucket.count;
    }
    // Nothing admitted in the window: the peer cannot be missing anything
    // from us.
    if (window > 0) {
        m_connman.ForNode(next, [&](CNode *node) {
            if (!node->fSuccessfullyConnected || node->fDisconnect) {
                return false;
            }
            MakeAndPushMessage(*node, NetMsgType::MERKLIXSYNC, summary);
            return true;
        });
        if (auto *m{node::GetNodeMetrics()}) {
            m->txrelay_recon_rounds.Inc();
        }
        LogEvent(BCLog::TXRELAY, "peer_recon_summary_sent",
                 "reconciliation summary of {count} transactions to "
                 "peer={peer_id}")
            .Field(BCLog::LogField::PeerId, next)
            .Field(BCLog::LogField::Count, window);
    }
    // Window entries older than the window are no longer needed.
    m_txrelay_index.PruneWindow(
        GetTime<std::chrono::microseconds>() -
        2 * std::chrono::microseconds{m_opts.txrecon_window});
}

void PeerManagerImpl::MaybeReconcile() {
    if (m_opts.txrecon_interval <= 0ms || !m_opts.txrelay_shortids ||
        m_chainman.IsInitialBlockDownload()) return;
    const auto now{RelayTickNow()};
    const auto epoch{m_txrelay_index.Current()};
    if (!epoch) return;
    const auto ticket{m_recon_scheduler.Begin(now)};
    if (!ticket) return;
    struct CaptureGuard {
        txrelay::ReconciliationScheduler &scheduler;
        std::chrono::microseconds now;
        bool completed{false};
        ~CaptureGuard() { if (!completed) scheduler.Cancel(now); }
    } guard{m_recon_scheduler, now};
    std::vector<NodeId> eligible;
    {
        LOCK(m_peer_mutex);
        for (const auto &[id, peer] : m_peer_map) {
            if (peer->m_txrelay_features & txrelay::TXRELAY_RECON)
                eligible.push_back(id);
        }
    }
    // Honest initiation pacing, independent of body request bookkeeping.
    // Leave room within the existing32/s inbound budget for drilldown traffic.
    // This is not a claim that a fresh multi-message exchange has completed.
    std::erase_if(eligible, [&](NodeId id) {
        const auto it = m_recon_last_sent.find(id);
        if (it != m_recon_last_sent.end() && now - it->second < 250ms)
            return true;
        return !m_connman.ForNode(id, [&](CNode *node) {
            return node->fSuccessfullyConnected && !node->fDisconnect &&
                   !node->fPauseSend;
        });
    });
    const auto count{TxRelayFanout(eligible.size(), m_opts.txrelay_fanout_min,
                                  m_opts.txrelay_fanout_pct,
                                  m_opts.txrelay_fanout_max)};
    std::optional<NodeId> fair_peer;
    const auto selected{m_recon_scheduler.Select(
        eligible, count, ticket->fairness, m_rng, &fair_peer)};
    bool sent{false};
    if (!selected.empty()) {
        const auto summary{m_v2_protocol_handler.BuildSyncSummary(
            lotus::v2::net::ReconScope::LIVE_MEMPOOL, epoch->epoch_id,
            epoch->k0, epoch->k1)};
        for (NodeId id : selected) {
            const bool delivered{m_connman.ForNode(id, [&](CNode *node) {
                if (!node->fSuccessfullyConnected || node->fDisconnect ||
                    node->fPauseSend) return false;
                MakeAndPushMessage(*node, NetMsgType::MERKLIXSYNC, summary);
                return true;
            })};
            if (!delivered) continue;
            sent = true;
            m_recon_last_sent[id] = now;
            if (fair_peer == id) m_recon_scheduler.FairDispatched(id, now);
            if (auto *metrics{node::GetNodeMetrics()})
                metrics->txrelay_recon_rounds.Inc();
        }
        if (sent) {
            const auto repeats{m_recon_scheduler.ObserveLocalRoot(
                summary.candidate_root, epoch->epoch_id, *ticket)};
            LogEvent(BCLog::TXRELAY, "recon_local_root_observed",
                     "local reconciliation capture repeated {count} times")
                .Field(BCLog::LogField::Count, uint64_t(repeats));
        }
    }
    m_recon_scheduler.Complete(*ticket, now, sent);
    guard.completed = true;
    // Retain only connection-local pacing state for connected relay peers.
    std::erase_if(m_recon_last_sent, [&](const auto &entry) {
        return !GetPeerRef(entry.first);
    });
    m_txrelay_index.PruneWindow(GetTime<std::chrono::microseconds>() -
        2 * std::chrono::microseconds{m_opts.txrecon_window});
}

