    scheduler.Changed(TxId{rng.rand256()}, 0ms);
    auto pass = scheduler.Begin(0ms);
    BOOST_REQUIRE(pass);
    scheduler.Cancel(1ms); // the production RAII guard uses this on exceptions
    BOOST_CHECK(!scheduler.Begin(10ms));
    auto retry = scheduler.Begin(11ms);
    BOOST_REQUIRE(retry);
    BOOST_CHECK_EQUAL(retry->generation, pass->generation);
    scheduler.Complete(*retry, 11ms, true);
}


BOOST_AUTO_TEST_CASE(reconciliation_full_next_generation_survives_capture) {
    txrelay::ReconciliationScheduler scheduler{3, 1s, 10ms, 0ms};
    FastRandomContext rng{true};
    for (int i = 0; i < 3; ++i) scheduler.Changed(TxId{rng.rand256()}, 0ms);
    auto first = scheduler.Begin(0ms);
    BOOST_REQUIRE(first);
    // A completely distinct threshold arrives while old A/B/C are captured.
    for (int i = 0; i < 3; ++i) scheduler.Changed(TxId{rng.rand256()}, 1ms);
    scheduler.Complete(*first, 1ms, true);
    BOOST_CHECK(!scheduler.ShouldWake(10ms));
    BOOST_CHECK(scheduler.ShouldWake(11ms));
    auto second = scheduler.Begin(11ms);
    BOOST_REQUIRE(second); // D/E/F remain a complete threshold, not just F
    for (int i = 0; i < 3; ++i) scheduler.Changed(TxId{rng.rand256()}, 12ms);
    scheduler.Complete(*second, 12ms, false);
    BOOST_CHECK(scheduler.ShouldWake(22ms));
    auto retry = scheduler.Begin(22ms);
    BOOST_REQUIRE(retry); // failed dispatch preserves the next full threshold
    scheduler.Complete(*retry, 22ms, true);
}

BOOST_AUTO_TEST_CASE(reconciliation_periodic_wake_tracks_quiet_deadline) {
    txrelay::ReconciliationScheduler scheduler{2, 25ms, 1ms, 5ms};
    FastRandomContext rng{true};
    BOOST_CHECK(!scheduler.Begin(0ms));
    BOOST_CHECK(!scheduler.ShouldWake(24ms));
    BOOST_CHECK(scheduler.ShouldWake(25ms)); // periodic relay callback uses this
    auto quiet = scheduler.Begin(25ms);
    BOOST_REQUIRE(quiet);
    scheduler.Complete(*quiet, 25ms, true);
    scheduler.Changed(TxId{rng.rand256()}, 26ms);
    scheduler.Changed(TxId{rng.rand256()}, 26ms);
    BOOST_CHECK(!scheduler.ShouldWake(30ms));
    BOOST_CHECK(scheduler.ShouldWake(31ms)); // removal-only/change-only count path
    auto count = scheduler.Begin(31ms);
    BOOST_REQUIRE(count);
    scheduler.Complete(*count, 31ms, true);
    BOOST_CHECK(!scheduler.ShouldWake(55ms));
    BOOST_CHECK(scheduler.ShouldWake(56ms)); // no-change discovery continues
}


