BOOST_AUTO_TEST_CASE(reconciliation_failed_fair_enqueue_does_not_advance_rotation) {
    txrelay::ReconciliationScheduler scheduler{1, 100ms, 1ms, 0ms};
    FastRandomContext rng{true};
    const std::vector<NodeId> peers{0, 1, 2};
    std::optional<NodeId> reserved;
    scheduler.Select(peers, 2, true, rng, &reserved);
    BOOST_REQUIRE(reserved);
    BOOST_CHECK_EQUAL(*reserved, 0);
    // Some random recipient may succeed while reserved0 pauses/disconnects.
    // No FairDispatched(0): the next fair pass must retain that obligation.
    scheduler.Select(peers, 2, true, rng, &reserved);
    BOOST_REQUIRE(reserved);
    BOOST_CHECK_EQUAL(*reserved, 0);
    scheduler.FairDispatched(*reserved, 100ms);
    scheduler.Select(peers, 2, true, rng, &reserved);
    BOOST_REQUIRE(reserved);
    BOOST_CHECK_EQUAL(*reserved, 1);
}


BOOST_AUTO_TEST_CASE(reconciliation_failed_mature_capture_retains_retry_readiness) {
    txrelay::ReconciliationScheduler scheduler{3, 1s, 10ms, 50ms};
    FastRandomContext rng{true};
    for (int i = 0; i < 3; ++i) scheduler.Changed(TxId{rng.rand256()}, 0ms);
    BOOST_CHECK(!scheduler.Begin(0ms));
    auto mature = scheduler.Begin(50ms);
    BOOST_REQUIRE(mature);
    for (int i = 0; i < 3; ++i) scheduler.Changed(TxId{rng.rand256()}, 51ms);
    scheduler.Complete(*mature, 51ms, false);
    BOOST_CHECK(!scheduler.ShouldWake(60ms));
    BOOST_CHECK(scheduler.ShouldWake(61ms)); // old ready obligation survived
    auto retry = scheduler.Begin(61ms);
    BOOST_REQUIRE(retry);
    BOOST_CHECK(retry->cutoff == 11ms); // payload margin was not bypassed
    scheduler.Cancel(62ms);
    BOOST_CHECK(scheduler.ShouldWake(72ms)); // cancellation retains it too
    auto resumed = scheduler.Begin(72ms);
    BOOST_REQUIRE(resumed);
    scheduler.Complete(*resumed, 72ms, true); // only actual dispatch retires it
    BOOST_CHECK(!scheduler.ShouldWake(82ms)); // newer DEF still needs its margin
    BOOST_CHECK(scheduler.ShouldWake(101ms));
    auto next_generation = scheduler.Begin(101ms);
    BOOST_REQUIRE(next_generation);
    scheduler.Complete(*next_generation, 101ms, true);
}

